begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','owner@example.invalid',now()),('22222222-2222-4222-8222-222222222222','other@example.invalid',now());
create temporary table fixture(key text primary key,id uuid);
grant all on fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into fixture values('brand',public.create_owner_workspace('Owner','Catalogue brand','UTC','','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true));
insert into fixture values('source',public.register_brand_source((select id from fixture where key='brand'),'shopify','Test shop','test.myshopify.com'));
select throws_ok($$select public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid())$$,'22023',null,'Unverified source cannot queue collection');
select throws_ok($$select * from private.connector_credentials$$,'42501',null,'Clients cannot read encrypted credentials');
select throws_ok($$select private.schedule_reconciliation()$$,'42501',null,'Clients cannot call privileged scheduler');
reset role;
update public.brand_sources set state='authorized',verified_account='test.myshopify.com',version=2,granted_scopes=array['read_products'] where id=(select id from fixture where key='source');
insert into private.connector_credentials(source_id,brand_id,encrypted_value,key_version,expires_at) values((select id from fixture where key='source'),(select id from fixture where key='brand'),'test-only-ciphertext','test',now()+interval '1 hour');
set local role authenticated;
insert into fixture values('run',public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'));
select is(public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),'bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),(select id from fixture where key='run'),'Sync retry returns same run');
select is(public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid()),(select id from fixture where key='run'),'Concurrent intent coalesces with active source run');
select is((select source_version from public.collection_runs),2,'Run records authorization generation');
select throws_ok($$insert into public.catalogue_records(brand_id,source_id,external_id,kind,title,payload,seen_run_id) values((select id from fixture where key='brand'),(select id from fixture where key='source'),'fake','product','Fake','{}',(select id from fixture where key='run'))$$,'42501',null,'Client cannot fabricate imported catalogue');
reset role;
select is((select count(*)::int from private.job_outbox),1,'Queue intent persisted atomically');
select ok(private.run_authorized((select id from fixture where key='run')),'Worker predicate allows current actor and generation');
update public.brand_memberships set active=false where user_id='11111111-1111-4111-8111-111111111111';
select ok(not private.run_authorized((select id from fixture where key='run')),'Revocation blocks queued worker execution');
update public.brand_memberships set active=true where user_id='11111111-1111-4111-8111-111111111111';
set local role authenticated;
select public.set_brand_source_state((select id from fixture where key='brand'),(select id from fixture where key='source'),2,'disabled');
select is((select state from public.collection_runs),'cancelled','Disconnect cancels pending run');
reset role;
select is((select count(*)::int from private.connector_credentials),0,'Disconnect erases stored credentials');
select ok(not private.run_authorized((select id from fixture where key='run')),'Disconnected source cannot commit a checkpoint');
update public.brand_sources set state='authorized',version=4 where id=(select id from fixture where key='source');
insert into private.connector_credentials(source_id,brand_id,encrypted_value,key_version,expires_at) values((select id from fixture where key='source'),(select id from fixture where key='brand'),'test-only-ciphertext','test',now()+interval '1 hour');
set local role authenticated;
select public.set_collection_allowance((select id from fixture where key='brand'),1);
select throws_ok($$select public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid())$$,'54000',null,'Consumed allowance blocks new work');
select is((select count(*)::int from public.collection_runs),1,'Exhaustion preserves existing records');
select set_config('request.jwt.claims','{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
select is((select count(*)::int from public.collection_runs),0,'Unrelated tenant cannot read runs');
select throws_ok($$select public.request_source_sync((select id from fixture where key='brand'),(select id from fixture where key='source'),gen_random_uuid())$$,'42501',null,'Unrelated actor cannot queue work');
select throws_ok($$select public.set_collection_allowance((select id from fixture where key='brand'),1000)$$,'42501',null,'Unrelated actor cannot raise quota');
reset role;
select * from finish();
rollback;
